-- Đồng bộ bảng "Places" và "PlaceTags" của DB đang chạy với places.seed.json (2026-10-05).
-- Chạy lại nhiều lần vẫn cho cùng kết quả. DB mới tạo không cần script này (seed đọc places.seed.json).
-- Khớp địa điểm theo tên; giữ nguyên Id nên trip, lịch mẫu, đánh giá cũ không đổi.
-- Tag của 65 địa điểm dưới đây được đưa về ĐÚNG danh sách trong cột tags (tag gán tay khác sẽ bị bỏ).
-- (2026-10-06) Thêm mã địa điểm Google Maps và toạ độ lấy theo Google: cần chạy migration
-- AddPlaceGooglePlaceId TRƯỚC (script dùng cột "GooglePlaceId").
\set ON_ERROR_STOP on
SET client_encoding = 'UTF8';
BEGIN;

CREATE TEMP TABLE sheet_places (
  name text PRIMARY KEY, category text, address text,
  latitude double precision, longitude double precision,
  cost_min numeric, cost_max numeric, description text, tags text[],
  google_place_id text
) ON COMMIT DROP;


-- 1. Địa điểm đã có: cập nhật mô tả, giá, địa chỉ, loại, toạ độ, mã Google Maps.
UPDATE "Places" p
SET "Description" = s.description,
    "Address" = s.address,
    "Category" = s.category,
    "EstimatedCostMin" = s.cost_min,
    "EstimatedCostMax" = s.cost_max,
    "Location" = ST_SetSRID(ST_MakePoint(s.longitude, s.latitude), 4326),
    "GooglePlaceId" = s.google_place_id,
    "UpdatedAt" = now()
FROM sheet_places s
WHERE p."Name" = s.name
  AND p."DeletedAt" IS NULL
  AND (p."Description", p."Address", p."Category", p."EstimatedCostMin", p."EstimatedCostMax",
       ST_X(p."Location"), ST_Y(p."Location"), p."GooglePlaceId")
      IS DISTINCT FROM (s.description, s.address, s.category, s.cost_min, s.cost_max,
       s.longitude, s.latitude, s.google_place_id);

-- 2. Địa điểm mới: thêm với trạng thái Active (giống seed).
                      "EstimatedCostMin", "EstimatedCostMax", "IsVerified", "GooglePlaceId",
                      "CreatedAt", "UpdatedAt")
SELECT gen_random_uuid(), s.name, s.description, s.address,
       ST_SetSRID(ST_MakePoint(s.longitude, s.latitude), 4326), s.category, 'Active',
       s.cost_min, s.cost_max, false, s.google_place_id, now(), now()
FROM sheet_places s
WHERE NOT EXISTS (SELECT 1 FROM "Places" p WHERE p."Name" = s.name);

-- 3. Tag: bỏ tag không còn trong danh sách, rồi thêm tag còn thiếu.
DELETE FROM "PlaceTags" pt
USING "Places" p, sheet_places s
WHERE pt."PlaceId" = p."Id"
  AND p."Name" = s.name
  AND pt."TagId" NOT IN (SELECT t."Id" FROM "Tags" t WHERE t."Name" = ANY (s.tags));

SELECT p."Id", t."Id"
FROM sheet_places s
JOIN "Places" p ON p."Name" = s.name
CROSS JOIN LATERAL unnest(s.tags) AS wanted(tag_name)
JOIN "Tags" t ON t."Name" = wanted.tag_name
ON CONFLICT DO NOTHING;

SELECT count(*) AS places,
       count(*) FILTER (WHERE "Status" = 'Active' AND "DeletedAt" IS NULL) AS active,
       count(DISTINCT "Name") AS distinct_names,
       (SELECT count(*) FROM "PlaceTags") AS place_tags
FROM "Places";

COMMIT;
